def choose_move(observation):
    dx = 0
    dy = 0

    # Basic position accessors with defaults
    pos = observation.get("self_position", observation.get("position", {}))
    ex = observation.get("opponent_position", observation.get("opponent", {}))
    if isinstance(pos, dict):
        px = pos.get("x", 0)
        py = pos.get("y", 0)
    else:
        px = 0
        py = 0
    if isinstance(ex, dict):
        ox = ex.get("x", px)
        oy = ex.get("y", py)
    else:
        ox = px
        oy = py

    # Resources: move toward nearest if present
    resources = observation.get("resources", [])
    if isinstance(resources, list) and resources:
        best = None
        best_dist = 10**9
        for r in resources:
            rx = r.get("x", None)
            ry = r.get("y", None)
            if rx is None or ry is None:
                continue
            dist = abs(px - rx) + abs(py - ry)
            if dist < best_dist:
                best_dist = dist
                best = (rx, ry)
        if best is not None and best_dist > 0:
            dx = 1 if best[0] > px else -1 if best[0] < px else 0
            dy = 1 if best[1] > py else -1 if best[1] < py else 0
            return [dx, dy]

    # Avoid crossing opponent: move away if neighbor
    if isinstance(ex, dict):
        if abs(px - ox) <= 1 and abs(py - oy) <= 1 and (px != ox or py != oy):
            if ox >= px:
                dx = -1
            elif ox < px:
                dx = 1
            else:
                dx = 0
            if oy >= py:
                dy = -1
            elif oy < py:
                dy = 1
            else:
                dy = 0
            return [dx, dy]

    # Fallback: move toward center of grid if available
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)
    if grid_w and grid_h:
        cx = grid_w // 2
        cy = grid_h // 2
        dx = 1 if cx > px else -1 if cx < px else 0
        dy = 1 if cy > py else -1 if cy < py else 0
        return [dx, dy]

    # Default stay
    return [0, 0]
